using System.IO;
using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media.Imaging;
using Microsoft.Win32;
namespace Campus.Desktop;

public sealed class Item(JsonNode data,string display){public JsonNode Data=data;public override string ToString()=>display;}
public sealed class MainWindow:Window {
 readonly ApiClient api;readonly TextBlock who=Ui.Text("游客 · 可浏览商品"),status=Ui.Text("正在读取商品…");readonly StackPanel actions=new(){Orientation=Orientation.Horizontal};readonly ListBox list=new(){MinHeight=140};readonly TextBox keyword=new();readonly ComboBox category=new(){ItemsSource=new[]{"全部","教材","数码","生活","其他"},SelectedIndex=0};readonly TextBlock heading=Ui.Text("商品大厅",24);readonly TextBlock pageText=Ui.Text("");
 string view="market";int page=1,total=0;bool loading;
 public MainWindow(ApiClient client){api=client;Title="校园二手交易系统";Width=1080;Height=800;MinWidth=880;MinHeight=650;WindowStartupLocation=WindowStartupLocation.CenterScreen;Ui.Theme(this);
  var root=new DockPanel{Margin=new Thickness(28)};Content=root;var top=new StackPanel();top.Children.Add(Ui.Text("校园二手交易",28));top.Children.Add(who);var nav=new WrapPanel();nav.Children.Add(Ui.Button("商品大厅(_1)",()=>Navigate("market")));nav.Children.Add(Ui.Button("我的商品(_2)",()=>Navigate("mine")));nav.Children.Add(Ui.Button("我的交易(_3)",()=>Navigate("trades")));nav.Children.Add(Ui.Button("个人资料(_4)",Profile));nav.Children.Add(Ui.Button("登录(_L)",Login));nav.Children.Add(Ui.Button("注册(_R)",Register));nav.Children.Add(Ui.Button("退出登录(_O)",()=>_=Logout()));top.Children.Add(nav);top.Children.Add(heading);
  var search=new Grid();search.ColumnDefinitions.Add(new(){Width=new GridLength(3,GridUnitType.Star)});search.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});search.ColumnDefinitions.Add(new(){Width=GridLength.Auto});var p1=new StackPanel{Margin=new Thickness(0,0,12,0)};Ui.Field(p1,"关键词",keyword);search.Children.Add(p1);var p2=new StackPanel{Margin=new Thickness(0,0,12,0)};Ui.Field(p2,"商品分类",category);Grid.SetColumn(p2,1);search.Children.Add(p2);var find=Ui.Button("搜索 / 刷新(_S)",()=>{page=1;_=Load();});find.VerticalAlignment=VerticalAlignment.Center;Grid.SetColumn(find,2);search.Children.Add(find);top.Children.Add(search);DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);
  var footer=new StackPanel();footer.Children.Add(actions);var paging=new StackPanel{Orientation=Orientation.Horizontal};paging.Children.Add(Ui.Button("上一页(_P)",()=>{if(page>1){page--;_=Load();}}));paging.Children.Add(pageText);paging.Children.Add(Ui.Button("下一页(_N)",()=>{if(page*20<total){page++;_=Load();}}));footer.Children.Add(paging);footer.Children.Add(status);footer.Children.Add(Ui.Text("Alt+1/2/3 切换页面 · Tab 移动焦点 · 方向键选择记录 · Enter 打开详情 · F5 刷新",13));DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);root.Children.Add(list);
  KeyboardNavigation.SetTabNavigation(top,KeyboardNavigationMode.Local);KeyboardNavigation.SetTabNavigation(footer,KeyboardNavigationMode.Local);KeyboardNavigation.SetTabIndex(top,0);KeyboardNavigation.SetTabIndex(list,1);KeyboardNavigation.SetTabIndex(footer,2);Ui.Name(list,"商品列表","使用上下方向键选择，Enter查看详情，Tab前往操作按钮。");
  list.MouseDoubleClick+=(_,_)=>Detail();list.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){Detail();e.Handled=true;}};keyword.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){page=1;_=Load();e.Handled=true;}};PreviewKeyDown+=(_,e)=>{if(e.Key==Key.F5){_=Load();e.Handled=true;}if(e.Key==Key.F6){list.Focus();e.Handled=true;}};Loaded+=async(_,_)=>{await Load();Ui.FocusFirst(this);};RebuildActions();
 }
 bool Auth(){if(api.User!=null)return true;Ui.Announce(status,"请先登录后再操作。");Login();return api.User!=null;}
 void Navigate(string next){if(next!="market"&&!Auth())return;view=next;page=1;heading.Text=next=="market"?"商品大厅":next=="mine"?"我的商品":"我的交易";Ui.Name(list,heading.Text+"列表","上下方向键选择，Enter查看详情。");RebuildActions();_=Load();}
 void RebuildActions(){actions.Children.Clear();actions.Children.Add(Ui.Button("查看详情(_D)",Detail));if(view=="market")actions.Children.Add(Ui.Button("申请购买(_B)",()=>_=Apply()));if(view=="mine"){actions.Children.Add(Ui.Button("发布商品(_A)",()=>Edit(null)));actions.Children.Add(Ui.Button("编辑商品(_E)",()=>{var item=Selected();if(item!=null)Edit(item);}));actions.Children.Add(Ui.Button("下架商品(_W)",()=>_=Withdraw()));}if(view=="trades"){actions.Children.Add(Ui.Button("接受申请(_A)",()=>_=TradeAction("accept")));actions.Children.Add(Ui.Button("拒绝申请(_J)",()=>_=TradeAction("reject")));actions.Children.Add(Ui.Button("取消申请(_X)",()=>_=TradeAction("cancel")));actions.Children.Add(Ui.Button("确认完成(_F)",()=>_=TradeAction("complete")));}}
 JsonNode? Selected(){if(list.SelectedItem is Item i)return i.Data;Ui.Announce(status,"请先用方向键选择一条记录。");list.Focus();return null;}
 async Task Load(){if(loading)return;loading=true;try{string url=view=="trades"?"/api/v1/trades":view=="mine"?"/api/v1/me/products":"/api/v1/products";url+=$"?page={page}&pageSize=20";if(view!="trades")url+="&keyword="+Uri.EscapeDataString(keyword.Text)+"&category="+Uri.EscapeDataString(category.SelectedIndex==0?"":category.SelectedItem?.ToString()??"");var data=await api.Call("GET",url);var old=(list.SelectedItem as Item)?.Data["id"]?.ToString();list.Items.Clear();foreach(var node in data["items"]!.AsArray()){var d=node!;string text=view=="trades"?$"{d["titleSnapshot"]} · ¥{int.Parse(d["priceSnapshot"]!.ToString())/100m:0.00} · {d["status"]} · {(d["role"]!.ToString()=="buyer"?"我是买家":"我是卖家")}":$"{d["title"]} · ¥{int.Parse(d["priceCents"]!.ToString())/100m:0.00} · {d["category"]} · {d["status"]}";var item=new Item(d,text);list.Items.Add(item);if(d["id"]!.ToString()==old)list.SelectedItem=item;}total=(int)data["total"]!;pageText.Text=$"第{page}页 / 共{Math.Max(1,(total+19)/20)}页";if(list.SelectedIndex<0&&list.Items.Count>0)list.SelectedIndex=0;Ui.Announce(status,$"已加载{list.Items.Count}条记录，共{total}条。" );}catch(Exception e){Ui.Announce(status,e.Message);}finally{loading=false;}}
 void Login(){var w=new FormWindow(this,"登录");var account=new TextBox();var pass=new PasswordBox();Ui.Field(w.Fields,"账号",account,"3至32位字母、数字或下划线");Ui.Field(w.Fields,"密码",pass);w.Submit("登录(_L)",async()=>{var data=await api.Call("POST","/api/v1/sessions",new{account=account.Text,password=pass.Password});api.Token=data["token"]!.ToString();api.User=data["user"]!.AsObject();who.Text="当前用户："+api.User["nickname"];w.Close();await Load();});w.ShowOwned();}
 void Register(){var w=new FormWindow(this,"注册账号");var account=new TextBox();var pass=new PasswordBox();var nickname=new TextBox();var contact=new TextBox();Ui.Field(w.Fields,"账号",account,"3至32位字母、数字或下划线");Ui.Field(w.Fields,"密码",pass,"至少8位；请勿使用真实账号的密码");Ui.Field(w.Fields,"昵称",nickname);Ui.Field(w.Fields,"联系方式",contact,"课程演示可填写虚构邮箱");w.Submit("注册(_R)",async()=>{await api.Call("POST","/api/v1/users",new{account=account.Text,password=pass.Password,nickname=nickname.Text,contact=contact.Text});w.Close();Ui.Announce(status,"注册成功，请登录。");});w.ShowOwned();}
 async Task Logout(){try{if(api.User!=null)await api.Call("DELETE","/api/v1/session");api.User=null;api.Token="";who.Text="游客 · 可浏览商品";Navigate("market");}catch(Exception e){Ui.Announce(status,e.Message);}}
 async void Profile(){if(!Auth())return;try{var u=await api.Call("GET","/api/v1/me");var w=new FormWindow(this,"个人资料");var nick=new TextBox{Text=u["nickname"]!.ToString()};var contact=new TextBox{Text=u["contact"]!.ToString()};w.Fields.Children.Add(Ui.Text("账号："+u["account"]));Ui.Field(w.Fields,"昵称",nick);Ui.Field(w.Fields,"联系方式",contact);w.Submit("保存(_S)",async()=>{var updated=await api.Call("PATCH","/api/v1/me",new{nickname=nick.Text,contact=contact.Text,version=(int)u["version"]!});api.User=updated.AsObject();who.Text="当前用户："+updated["nickname"];w.Close();Ui.Announce(status,"资料已保存。");});w.ShowOwned();}catch(Exception e){Ui.Announce(status,e.Message);}}
 void Edit(JsonNode? p){if(!Auth())return;var w=new FormWindow(this,p==null?"发布商品":"编辑商品");var title=new TextBox{Text=p?["title"]?.ToString()??""};var cat=new ComboBox{ItemsSource=new[]{"教材","数码","生活","其他"},SelectedItem=p?["category"]?.ToString()??"教材"};var price=new TextBox{Text=p==null?"":((int)p["priceCents"]!/100m).ToString("0.00")};var desc=new TextBox{Text=p?["description"]?.ToString()??"",AcceptsReturn=true,Height=95,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};var images=p?["imageIds"]?.AsArray().Select(x=>x!.ToString()).ToList()??new List<string>();Ui.Field(w.Fields,"商品标题",title,"最多80字");Ui.Field(w.Fields,"分类",cat);Ui.Field(w.Fields,"价格（元）",price,"0.01至10000.00，最多两位小数");Ui.Field(w.Fields,"商品描述",desc,"最多1000字；请描述成色和交接方式");var imageInfo=Ui.Text($"已选{images.Count}张图片");w.Fields.Children.Add(imageInfo);
  var upload=Ui.Button("选择图片(_I)",()=>{});upload.Click+=async(_,_)=>{var picker=new OpenFileDialog{Filter="图片|*.png;*.jpg;*.jpeg",Multiselect=true,Title="选择1至3张商品图片"};if(picker.ShowDialog(w)!=true)return;upload.IsEnabled=false;try{if(picker.FileNames.Length>3)throw new Exception("最多3张图片。");var next=new List<string>();foreach(var file in picker.FileNames){if(new FileInfo(file).Length>2097152)throw new Exception("图片不得超过2 MiB。");var data=await api.Call("POST","/api/v1/images",new{fileName=Path.GetFileName(file),mimeType=Path.GetExtension(file).ToLowerInvariant()==".png"?"image/png":"image/jpeg",contentBase64=Convert.ToBase64String(await File.ReadAllBytesAsync(file))});next.Add(data["imageId"]!.ToString());}images=next;imageInfo.Text=$"已选{images.Count}张图片："+string.Join("、",picker.FileNames.Select(Path.GetFileName));Ui.Announce(w.Status,"图片已上传，提交商品后生效。");}catch(Exception e){Ui.Announce(w.Status,e.Message);}finally{upload.IsEnabled=true;}};w.Fields.Children.Add(upload);
  w.Submit("提交审核(_S)",async()=>{if(string.IsNullOrWhiteSpace(title.Text)||string.IsNullOrWhiteSpace(desc.Text))throw new Exception("标题和描述不能为空。");if(!decimal.TryParse(price.Text,out var value)||value<=0||value>10000||value*100!=decimal.Truncate(value*100))throw new Exception("价格必须为0.01至10000.00，且最多两位小数。");if(images.Count==0)throw new Exception("请至少选择一张图片。");var body=new JsonObject{["title"]=title.Text,["category"]=cat.SelectedItem?.ToString(),["description"]=desc.Text,["priceCents"]=(int)(value*100),["imageIds"]=new JsonArray(images.Select(x=>(JsonNode?)JsonValue.Create(x)).ToArray())};if(p!=null)body["version"]=(int)p["version"]!;await api.Call(p==null?"POST":"PATCH",p==null?"/api/v1/products":"/api/v1/products/"+p["id"],body);w.Close();await Load();Ui.Announce(status,"已提交审核。按F5刷新查看状态。");});w.ShowOwned();}
 async void Detail(){var p=Selected();if(p==null)return;try{var d=await api.Call("GET",(view=="trades"?"/api/v1/trades/":"/api/v1/products/")+p["id"]);var w=new FormWindow(this,"记录详情");if(view=="trades"){w.Fields.Children.Add(Ui.Text("商品："+d["titleSnapshot"],22));w.Fields.Children.Add(Ui.Text($"成交价格：¥{(int)d["priceSnapshot"]!/100m:0.00}\n状态：{d["status"]}\n我的身份：{(d["role"]!.ToString()=="buyer"?"买家":"卖家")}"));w.Fields.Children.Add(Ui.Text("对方联系方式："+(d["counterpartyContact"]?.ToString()??"接受交易后可见")));}else{w.Fields.Children.Add(Ui.Text(d["title"]!.ToString(),22));w.Fields.Children.Add(Ui.Text($"价格：¥{(int)d["priceCents"]!/100m:0.00}\n分类：{d["category"]}\n状态：{d["status"]}\n卖家：{d["sellerNickname"]}\n描述：{d["description"]}\n审核说明：{d["reviewReason"]}"));foreach(var id in d["imageIds"]!.AsArray()){try{var pic=await api.Call("GET","/api/v1/images/"+id);var b=new BitmapImage();using var mem=new MemoryStream(Convert.FromBase64String(pic["contentBase64"]!.ToString()));b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.StreamSource=mem;b.EndInit();var img=new Image{Source=b,MaxHeight=220,Margin=new Thickness(0,8,0,8)};Ui.Name(img,"商品图片："+d["title"]+"。"+d["description"]);w.Fields.Children.Add(img);}catch{w.Fields.Children.Add(Ui.Text("图片暂不可用，请参考商品描述。"));}}}w.ShowOwned();}catch(Exception e){Ui.Announce(status,e.Message);}}
 async Task Apply(){if(!Auth())return;var p=Selected();if(p==null)return;await Run(async()=>{await api.Call("POST","/api/v1/trades",new{productId=p["id"]!.ToString(),productVersion=(int)p["version"]!});},"购买申请已提交，可到我的交易查看。");}
 async Task Withdraw(){var p=Selected();if(p==null)return;if(MessageBox.Show(this,"下架后，未处理的申请将被拒绝。是否继续？","确认下架",MessageBoxButton.YesNo,MessageBoxImage.Question,MessageBoxResult.No)!=MessageBoxResult.Yes)return;await Run(async()=>{await api.Call("POST","/api/v1/products/"+p["id"]+"/withdraw",new{version=(int)p["version"]!});},"商品已下架。");}
 async Task TradeAction(string action){var p=Selected();if(p==null)return;if(action=="complete"&&MessageBox.Show(this,"请确认已完成线下交接。确认后商品将标记为已售出。","确认完成",MessageBoxButton.YesNo,MessageBoxImage.Question,MessageBoxResult.No)!=MessageBoxResult.Yes)return;await Run(async()=>{var body=new JsonObject{["version"]=(int)p["version"]!};if(action!="cancel")body["productVersion"]=(int)p["productVersion"]!;await api.Call("POST","/api/v1/trades/"+p["id"]+"/"+action,body);},"操作成功，交易状态已更新。");}
 async Task Run(Func<Task> f,string success){actions.IsEnabled=false;try{await f();await Load();Ui.Announce(status,success);}catch(Exception e){Ui.Announce(status,e.Message);}finally{actions.IsEnabled=true;}}
}
